import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Multi-Site at Scale: Bloomberg’s Disaster Recovery Journey","description":"","frontmatter":{"title":"Ceph Multi-Site at Scale: Bloomberg’s Disaster Recovery Journey","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","灾难恢复","多站点部署","Bloomberg"],"categories":["技术分享"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Multi-Site_at_Scale_-_Bloomberg_s_Disaster_Recovery_Journey.md","filePath":"posts/2023/Ceph_Multi-Site_at_Scale_-_Bloomberg_s_Disaster_Recovery_Journey.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Multi-Site_at_Scale_-_Bloomberg_s_Disaster_Recovery_Journey.md"};function t(h,e,s,n,u,_){return l(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-bloomberg的ceph多站点部署与灾难恢复之旅" tabindex="-1">会议主题：Bloomberg的Ceph多站点部署与灾难恢复之旅 <a class="header-anchor" href="#会议主题-bloomberg的ceph多站点部署与灾难恢复之旅" aria-label="Permalink to &quot;会议主题：Bloomberg的Ceph多站点部署与灾难恢复之旅&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Jane Zhu，Bloomberg高级软件工程师</li><li>Teda，Bloomberg分布式存储团队成员</li></ul><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li><strong>介绍</strong>：Bloomberg及其分布式存储团队的工作介绍。</li><li><strong>Ceph集群概览</strong>：展示Bloomberg云存储（BCS）中的Ceph集群。</li><li><strong>多站点旅程</strong>：深入探讨如何采用Ceph的多站点功能。</li><li><strong>未来计划</strong>：讨论集群升级和监控改进。</li><li><strong>问答环节</strong>：回答与会者的提问。</li></ol><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><h5 id="_1-介绍" tabindex="-1">1. 介绍 <a class="header-anchor" href="#_1-介绍" aria-label="Permalink to &quot;1. 介绍&quot;">​</a></h5><ul><li>Bloomberg是一家全球性的金融科技公司，提供新闻、分析和软件服务。</li><li>分布式存储团队负责设计和维护BCS，支持文件系统、块设备和对象存储。</li><li>BCS使用Ceph作为后端存储，每天处理超过10亿次请求。</li></ul><h5 id="_2-ceph集群概览" tabindex="-1">2. Ceph集群概览 <a class="header-anchor" href="#_2-ceph集群概览" aria-label="Permalink to &quot;2. Ceph集群概览&quot;">​</a></h5><ul><li>BCS集群包含四个数据中心，总存储容量约为65PB。</li><li>集群分为Legacy PCS产品和新的支持多站点功能的集群。</li></ul><h5 id="_3-多站点旅程" tabindex="-1">3. 多站点旅程 <a class="header-anchor" href="#_3-多站点旅程" aria-label="Permalink to &quot;3. 多站点旅程&quot;">​</a></h5><ul><li>为解决灾难恢复问题，团队采用了Ceph的多站点功能，实现跨数据中心的数据复制。</li><li>通过测试和调试，解决了多站点复制问题，并与社区合作修复了相关代码。</li><li>讨论了多站点配置、硬件配置、数据差异处理等细节。</li></ul><h5 id="_4-未来计划" tabindex="-1">4. 未来计划 <a class="header-anchor" href="#_4-未来计划" aria-label="Permalink to &quot;4. 未来计划&quot;">​</a></h5><ul><li>计划将集群升级到最新Ceph版本，利用新功能和修复。</li><li>关注监控和复制延迟问题，寻求社区支持。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>与Ceph社区合作，优化多站点功能。</li><li>考虑开源内部工具和CI/CD管道。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>升级现有集群到最新Ceph版本。</li><li>开发或集成更好的监控工具。</li><li>继续参与社区活动，推动Ceph的发展和改进。</li></ul><h4 id="问答环节" tabindex="-1">问答环节： <a class="header-anchor" href="#问答环节" aria-label="Permalink to &quot;问答环节：&quot;">​</a></h4><ul><li>讨论了多站点配置、测试环境、数据差异处理等细节。</li><li>确认了测试环境硬件配置接近生产环境。</li><li>解释了在主动-主动模式下处理数据差异的策略。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>Jane Zhu和Teda感谢社区支持，并邀请有兴趣的人才加入Bloomberg。</li><li>会议在掌声中结束，参会者期待未来与Bloomberg和Ceph社区的进一步合作。</li></ul>',25)])])}const b=a(r,[["render",t]]);export{c as __pageData,b as default};
